// Judge.me reviews API レスポンスを BQ row に展開
// レスポンス: { reviews: [ {id, rating, title, body, reviewer, product_external_id, ...} ], current_page, per_page, total }
// 1 page あたり最大 100 reviews、複数ページに渡る場合は n8n pagination で連結される

const now = new Date().toISOString();
const rows = [];
const toBool = v => v === true || v === 'true' || v === 1;

for (const item of $input.all()) {
  const body = item.json;
  // エラー時の error フィールド対応
  if (!body || body.error || !Array.isArray(body.reviews)) {
    if (body && body.error) throw new Error('Judge.me API error: ' + JSON.stringify(body).substring(0, 500));
    continue;
  }
  for (const r of body.reviews) {
    if (!r || r.id == null) continue;
    const reviewer = r.reviewer || {};
    const pictures = Array.isArray(r.pictures) ? r.pictures : [];
    rows.push({
      review_id:               Number(r.id),
      product_external_id:     r.product_external_id != null ? String(r.product_external_id) : null,
      product_handle:          r.product_handle || (r.product && r.product.handle) || null,
      product_title:           r.product_title  || (r.product && r.product.title)  || null,
      rating:                  r.rating != null ? Number(r.rating) : null,
      title:                   r.title || null,
      body:                    r.body  || null,
      reviewer_name:           reviewer.name  || r.reviewer_name  || null,
      reviewer_email:          reviewer.email || r.reviewer_email || null,
      verified:                r.verified || null,
      verified_buyer:          (r.verified === 'verified-purchase' || r.verified === 'confirmed-buyer'),
      curated:                 r.curated   || null,
      published:               toBool(r.published),
      hidden:                  toBool(r.hidden),
      featured:                toBool(r.featured),
      source:                  r.source || null,
      ip_address:              r.ip_address || null,
      has_published_pictures:  toBool(r.has_published_pictures),
      has_published_videos:    toBool(r.has_published_videos),
      pictures_json:           pictures.length ? JSON.stringify(pictures).substring(0, 50000) : null,
      review_created_at:       r.created_at || null,
      review_updated_at:       r.updated_at || null,
      raw_payload:             JSON.stringify(r).substring(0, 100000),
      inserted_at:             now
    });
  }
}

return rows.map(json => ({ json }));
